mapper.select:
		select  FFCRD.LEV lev,
				FFCRD.BASE_RULE_ID baseRuleId,
				FFCRD.COEFFICIENT coefficient,
				FFCRD.SPREAD_RATE * 100 spreadRate,
				FFCRD.CHARGE_RATIO * 100 chargeRatio
		from FIN_FLOAT_CALC_RULE_DETAIL FFCRD, FIN_CASH_INFO FCI, FIN_PRODUCT FP, FIN_PRODUCT_ADD FPA
		where FFCRD.CASH_ID = FCI.CASH_ID
		  and FCI.FINPROD_ID = FP.FINPROD_ID
		  and FCI.FINPROD_ID = FPA.FINPROD_ID
		  and FCI.CASH_TYPE_1 = #{cashType1}
		  and FCI.CASH_TYPE_2 = #{cashType2}
		  and FCI.BRANCH = 0
		   AND ((FCI.FINPROD_ID = #{finprodId}

		   			and FPA.DEAL_MODE != #{dealMode10}

		   		)
           			OR (FP.P_FINPROD_ID = #{finprodId}

          		 	and FPA.DEAL_MODE = #{dealMode10}

           		AND FPA.TERM_TYPE != #{termType02}))
		   and FCI.FINPROD_TYPE = #{finprodType}


		   		and FFCRD.EFF_DATE = STR_TO_DATE(#{effDate},'%Y-%m-%d')


		   		and (FFCRD.EFF_DATE = FP.VDATE
		   		     OR FP.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})


		  order by FFCRD.LEV
